// Page and component text (HD-13): every sentence, label and message that a page or a component
// shows, in English, keyed by where it is used (`p.<route>.<words>` for a page,
// `c.<Component>.<words>` for a component). English is the source of truth.
//
// These keys are filled in with plain `{name}` interpolation (see `translate` in
// `i18n.svelte.ts`), not message-format syntax: a value is printed exactly as the page used to
// print it (no locale number formatting, no bidi marks), and there are no plural rules here.
// A count that changes the wording is two keys (`..._one`, `..._other`) chosen in code.
//
// Welsh (`cy-001`) is complete for this set (see `i18n-pages.cy.ts`). The other locales fall back
// to English for these keys until they are translated; `tests/unit/catalogue-coverage.test.ts`
// pins both facts.

